{
  "source": {
    "id": "MISMATCH-SOURCE-1",
    "version": 1,
    "scope": "Fictional test tiles completed in the same stipulated window within this case; counts, not rates.",
    "unit": "tiles",
    "windowId": "MISMATCH-WINDOW-1",
    "records": [
      {
        "id": "A",
        "completedCount": 80
      },
      {
        "id": "B",
        "completedCount": 90
      }
    ],
    "provenance": "author-created synthetic fixture; no measured production"
  },
  "sourceHash": "d8ea17d5467ee65ce02b557f2cbc24c6a3db583acae6f10d3ea803e967c5f425",
  "originalDisplay": {
    "id": "MISMATCH-ORIGINAL-1",
    "version": 1,
    "statement": {
      "id": "MISMATCH-TWICE-1",
      "predicate": "TWICE_COUNT",
      "predicateVersion": 1,
      "text": "B completed twice as many tiles as A."
    },
    "scale": {
      "lowerBound": 70,
      "upperBound": 100,
      "plotWidth": 240,
      "ticks": [
        70,
        80,
        90,
        100
      ]
    },
    "mark": "horizontal-length",
    "sourceOrder": [
      "A",
      "B"
    ]
  },
  "originalDisplayHash": "4df233c071f40f56d88bfb85d236f9a16c1ca24f636337aca14035aa55f2b5a1",
  "predicate": {
    "id": "TWICE_COUNT",
    "version": 1,
    "definition": "B.completedCount == 2 * A.completedCount",
    "unit": "tiles",
    "ratioNotNeededToDecideEquality": true
  },
  "correctionDisplay": {
    "id": "MISMATCH-CORRECTED-1",
    "version": 1,
    "text": "B completed 90 tiles; A completed 80. B completed 10 more tiles, or 9/8 as many.",
    "scale": {
      "lowerBound": 0,
      "upperBound": 100,
      "plotWidth": 240,
      "ticks": [
        0,
        20,
        40,
        60,
        80,
        100
      ]
    },
    "mark": "horizontal-length",
    "sourceOrder": [
      "A",
      "B"
    ],
    "debrief": "The original headline is false: 90 is not twice 80. Subtracting a baseline of 70 produces lengths 10 and 20, whose ratio is 2. Those lengths are offsets, not completed counts. The corrected chart starts at zero and preserves the original source. This authored example does not show that a person was persuaded."
  }
}

